def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opps = []
    prev_bids = []
    aggressive_bids = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opps.append(opp)
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                bid = prev.get('bid', 0)
                prev_bids.append(bid)
                if bid >= 0.75 * opp.get('daily_salary', DAILY_SALARY):
                    aggressive_bids.append(bid)

    if not alive_opps:
        safe = 0.35 * DAILY_SALARY
        if hp <= 2 or no_water_days >= 1:
            safe = 0.75 * DAILY_SALARY
        return max(0.0, min(budget, safe))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0
    alive_count = len(alive_opps)

    tight_supply = supply <= 17
    ample_supply = supply >= 22

    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1
    if no_water_days >= 2:
        urgency += 3
    elif no_water_days >= 1:
        urgency += 2
    if tight_supply:
        urgency += 1

    if urgency >= 5:
        bid = max(0.95 * DAILY_SALARY, highest_prev + 2.5)
    elif urgency >= 3:
        bid = max(0.82 * DAILY_SALARY, highest_prev + 1.6)
    else:
        if ample_supply:
            bid = max(0.28 * DAILY_SALARY, avg_prev * 0.6)
        elif tight_supply:
            bid = max(0.52 * DAILY_SALARY, highest_prev + 1.2)
        else:
            bid = max(0.42 * DAILY_SALARY, avg_prev * 0.85 + 0.8)

    if aggressive_bids and urgency <= 2 and hp >= 7 and no_water_days == 0:
        bid = min(bid, 0.48 * DAILY_SALARY)

    if alive_count >= 3 and supply <= 16:
        bid = max(bid, highest_prev + 1.8)

    if budget < 2 * DAILY_SALARY:
        bid = min(bid, max(0.35 * DAILY_SALARY, budget * 0.55))
    elif budget > 8 * DAILY_SALARY and (tight_supply or urgency >= 3):
        bid = max(bid, highest_prev + 2.0)

    if day >= 8 and hp >= 7 and no_water_days == 0 and not tight_supply:
        bid = min(bid, 0.4 * DAILY_SALARY)

    return max(0.0, min(budget, bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = {k: v for k, v in opponents_status.items() if v['alive']}
    if not alive_opponents:
        return min(budget, DAILY_SALARY * 0.3)

    # Collect yesterday's bids from opponents who have previous_trace
    yesterday_bids = []
    for opp in alive_opponents.values():
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    # Determine base bid
    if hp <= 3:
        # Desperate: bid high to secure water
        bid = DAILY_SALARY * 0.9
    else:
        # Competitive: use yesterday's bids
        if yesterday_bids:
            avg_prev = sum(yesterday_bids) / len(yesterday_bids)
            # Slightly above average, but cap at 0.6 salary to conserve
            bid = min(avg_prev * 1.1 + 1, DAILY_SALARY * 0.6)
        else:
            bid = DAILY_SALARY * 0.4

    # Adjust for supply: if supply low, increase bid
    supply_ratio = supply / 25.0
    if supply_ratio < 0.7:
        bid *= 1.2
    elif supply_ratio > 0.9:
        bid *= 0.9

    # Ensure we don't exceed budget and minimum 0
    bid = min(budget, max(0, bid))
    return bid
